//! Close the complete padded open visibility map without its spherical dual.
//!
//! Canonical Left endpoints and reversed Right endpoints are merged in input
//! order, retaining chord/slot identities until their physical contacts have
//! been attached. Original polygon edges then close the seam directly. Only
//! finite rays generated by original vertices survive; padding, null, and
//! infinity geometry does not belong to the closed subdivision.
//!
//! The physical graph has degree at most four. Constant-size exact rotations
//! and face walks take linear work; neither coordinates nor per-edge contacts
//! are hashed or globally sorted. Boundary-dart labels distinguish interior
//! cells from bounded exterior faces. Landing points remember their ORIGINAL
//! level generator, so a cell cap never becomes a landing-site vertex ID.
use crate::boundary::{Boundary, BoundaryError, Side, Site, Slot};
use crate::geometry::{Point, Rational, Route, orientation};
use crate::input::{Input, VertexId, VertexSource};
use crate::reduction::Cell;
use crate::submap::{MapError, Submap};
use crate::work::Work;
use num_traits::{One, Zero};
use std::cmp::Ordering;
use std::fmt;

#[derive(Debug)]
pub struct ClosedVisibility<'a> {
    pub vertices: Vec<&'a Point>,
    pub cells: Vec<Cell>,
}

#[derive(Debug)]
pub enum ClosureError {
    NotPolygon,
    NotFullChain,
    DirtyNormalForm,
    MissingOriginalSource { vertex: usize, side: Side, slot: Slot },
    InvalidEmbedding,
    InvalidCell,
    InvalidCapIncidence { vertex: usize, expected: usize, actual: usize },
    Boundary(BoundaryError),
    Map(MapError),
}
impl fmt::Display for ClosureError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result { write!(f, "{self:?}") }
}
impl std::error::Error for ClosureError {}
impl From<BoundaryError> for ClosureError {
    fn from(error: BoundaryError) -> Self { Self::Boundary(error) }
}
impl From<MapError> for ClosureError {
    fn from(error: MapError) -> Self { Self::Map(error) }
}

#[derive(Clone, Copy)]
struct Endpoint<'s> {
    site: &'s Site,
    chord: usize,
    slot: usize,
    generator: usize,
}

// The side/slot flags distinguish topological endpoints, not positions on the
// physical curve. These comparisons are used only to merge already ordered runs.
fn position_cmp(a: &Site, b: &Site, work: &mut Work) -> Ordering {
    work.predicates += 1;
    match (a, b) {
        (Site::Vertex { vertex: a, .. }, Site::Vertex { vertex: b, .. }) => a.cmp(b),
        (Site::Vertex { vertex, .. }, Site::Edge { edge, .. }) => {
            if vertex.0 <= edge.0 { Ordering::Less } else { Ordering::Greater }
        }
        (Site::Edge { edge, .. }, Site::Vertex { vertex, .. }) => {
            if edge.0 < vertex.0 { Ordering::Less } else { Ordering::Greater }
        }
        (Site::Edge { edge: a, t: at, .. }, Site::Edge { edge: b, t: bt, .. }) => {
            a.cmp(b).then_with(|| at.cmp(bt))
        }
    }
}
fn vertex_position_cmp(vertex: VertexId, site: &Site, work: &mut Work) -> Ordering {
    work.predicates += 1;
    match site {
        Site::Vertex { vertex: other, .. } => vertex.cmp(other),
        Site::Edge { edge, .. } => {
            if vertex.0 <= edge.0 { Ordering::Less } else { Ordering::Greater }
        }
    }
}
fn original_vertex(input: &Input, site: &Site) -> Option<usize> {
    if let Site::Vertex { vertex, .. } = site {
        if let VertexSource::Original(original) = input.source(*vertex) { return Some(*original); }
    }
    None
}
fn source_bit(side: Side, slot: Slot) -> u8 {
    let offset = if side == Side::Left { 0 } else { 3 };
    1 << (offset + match slot { Slot::Single => 0, Slot::Incoming => 1, Slot::Outgoing => 2 })
}

#[derive(PartialEq, Eq)]
struct Contact { edge: usize, t: Rational }
impl Contact {
    fn vertex(vertex: usize) -> Self { Self { edge: vertex, t: Rational::zero() } }
    fn new(edge: usize, t: Rational, n: usize) -> Result<Self, ClosureError> {
        if edge >= n || t < Rational::zero() || t > Rational::one() {
            return Err(ClosureError::InvalidEmbedding);
        }
        Ok(if t.is_one() { Self::vertex((edge + 1) % n) } else { Self { edge, t } })
    }
    fn of(input: &Input, site: &Site) -> Result<Self, ClosureError> {
        let (edge, t) = match site {
            Site::Vertex { vertex, .. } => match input.source(*vertex) {
                VertexSource::Original(original) => return Ok(Self::vertex(*original)),
                VertexSource::Seam { edge, t, .. } | VertexSource::Padding { edge, t } => (*edge, t.clone()),
            },
            Site::Edge { edge, t, .. } => input.original_contact(*edge, t),
        };
        Self::new(edge, t, input.original_len())
    }
}

enum PhysicalPoint<'a> { Original(&'a Point), Landing(Point) }
impl PhysicalPoint<'_> {
    fn point(&self) -> &Point { match self { Self::Original(point) => point, Self::Landing(point) => point } }
}
struct Node<'a> {
    contact: Contact,
    point: PhysicalPoint<'a>,
    generator: usize,
    outgoing: [usize; 4],
    degree: usize,
}

fn attach_contact<'a>(
    nodes: &mut Vec<Node<'a>>, contact: Contact, generator: usize,
    vertices: &[&'a Point], work: &mut Work,
) -> Result<usize, ClosureError> {
    work.retained_visits += 1;
    if let Some(last) = nodes.last() {
        work.predicates += 1;
        if last.contact == contact {
            if last.generator != generator { return Err(ClosureError::InvalidEmbedding); }
            return Ok(nodes.len() - 1);
        }
    }
    let point = if contact.t.is_zero() {
        if contact.edge != generator { return Err(ClosureError::InvalidEmbedding); }
        PhysicalPoint::Original(vertices[contact.edge])
    } else {
        let a = vertices[contact.edge];
        let b = vertices[(contact.edge + 1) % vertices.len()];
        let point = Point::new(
            &a.x + &contact.t * (&b.x - &a.x),
            &a.y + &contact.t * (&b.y - &a.y),
        );
        work.predicates += 1;
        if point.y != vertices[generator].y { return Err(ClosureError::InvalidEmbedding); }
        PhysicalPoint::Landing(point)
    };
    nodes.push(Node { contact, point, generator, outgoing: [usize::MAX; 4], degree: 0 });
    Ok(nodes.len() - 1)
}

#[derive(Clone, Copy)]
struct Dart {
    tail: usize,
    head: usize,
    twin: usize,
    rot_prev: usize,
    support: Option<usize>,
    inside_left: Option<bool>,
}
fn add_edge(
    nodes: &mut [Node<'_>], darts: &mut Vec<Dart>, a: usize, b: usize,
    support: Option<usize>, forward_inside: Option<bool>,
) -> Result<(), ClosureError> {
    if a == b || nodes[a].degree == 4 || nodes[b].degree == 4 {
        return Err(ClosureError::InvalidEmbedding);
    }
    let first = darts.len();
    for (tail, head, twin, inside_left) in [
        (a, b, first + 1, forward_inside),
        (b, a, first, forward_inside.map(|inside| !inside)),
    ] {
        let node = &mut nodes[tail];
        node.outgoing[node.degree] = darts.len();
        node.degree += 1;
        darts.push(Dart { tail, head, twin, rot_prev: usize::MAX, support, inside_left });
    }
    Ok(())
}
fn angular_cmp(nodes: &[Node<'_>], tail: usize, a: usize, b: usize, work: &mut Work) -> Ordering {
    let origin = nodes[tail].point.point();
    let a = nodes[a].point.point();
    let b = nodes[b].point.point();
    let upper = |point: &Point| point.y > origin.y || (point.y == origin.y && point.x > origin.x);
    work.predicates += 1;
    match upper(b).cmp(&upper(a)) {
        Ordering::Equal => orientation(origin, a, b).reverse(),
        order => order,
    }
}
fn edge_x(vertices: &[&Point], edge: usize, y: &Rational) -> Rational {
    let a = vertices[edge];
    let b = vertices[(edge + 1) % vertices.len()];
    &a.x + (y - &a.y) * (&b.x - &a.x) / (&b.y - &a.y)
}

/// Extract all positive-area interior cells of a complete original visibility
/// map on the full padded open chain. Geometric visibility is certified by the
/// map's producer; closure checks source coverage and the local closed-cell
/// contract without rediscovering ray contacts by scanning polygon edges.
pub fn close_visibility<'a>(map: &Submap<'a>, work: &mut Work) -> Result<ClosedVisibility<'a>, ClosureError> {
    let input = map.input();
    if !input.is_polygon() { return Err(ClosureError::NotPolygon); }
    if map.chain().start != VertexId(0) || map.chain().end != VertexId(input.len() - 1) {
        return Err(ClosureError::NotFullChain);
    }
    let boundary = Boundary::new(input, map.chain())?;
    let n = input.original_len();
    let mut original_points = vec![None; n];
    let mut original_order = Vec::with_capacity(n);
    for index in 0..input.len() {
        work.retained_visits += 1;
        let vertex = VertexId(index);
        if let VertexSource::Original(original) = input.source(vertex) {
            if *original >= n || original_points[*original].replace(input.vertex(vertex)).is_some() {
                return Err(ClosureError::InvalidEmbedding);
            }
            original_order.push((vertex, *original));
        }
    }
    let vertices: Vec<&Point> = original_points.into_iter()
        .collect::<Option<Vec<_>>>().ok_or(ClosureError::InvalidEmbedding)?;
    let count = map.chord_ids().count();
    let mut chord_generators = Vec::with_capacity(count);
    let mut covered = vec![0u8; n];
    for (index, id) in map.chord_ids().enumerate() {
        work.retained_visits += 1;
        if id.0 != index { return Err(ClosureError::DirtyNormalForm); }
        let (ends, route) = map.chord(id)?;
        let mut generator = None;
        for site in ends {
            boundary.validate_site(site)?;
            if let Some(original) = original_vertex(input, site) {
                let Site::Vertex { side, slot, .. } = site else { unreachable!() };
                let bit = source_bit(*side, *slot);
                if covered[original] & bit != 0 { return Err(ClosureError::InvalidEmbedding); }
                covered[original] |= bit;
                if generator.replace(original).is_some_and(|old| old != original) {
                    return Err(ClosureError::InvalidEmbedding);
                }
            }
        }
        chord_generators.push(if route == Route::Finite { generator } else { None });
    }
    for &(vertex, original) in &original_order {
        let slots: &[Slot] = if boundary.is_extremum(vertex) { &[Slot::Incoming, Slot::Outgoing] } else { &[Slot::Single] };
        for side in [Side::Left, Side::Right] {
            for &slot in slots {
                if covered[original] & source_bit(side, slot) == 0 {
                    return Err(ClosureError::MissingOriginalSource { vertex: original, side, slot });
                }
            }
        }
    }

    // Dirty/absent canonical order cannot support a linear physical merge.
    let canonical = map.canonical_arcs();
    if count == 0 || canonical.len() != 2 * count { return Err(ClosureError::DirtyNormalForm); }
    let mut endpoint_seen = vec![[false; 2]; count];
    let mut left = Vec::new();
    let mut right = Vec::new();
    let mut previous_site = None;
    for (i, &arc) in canonical.iter().enumerate() {
        work.retained_visits += 1;
        let (start, end, full) = map.arc_sites(arc).ok_or(ClosureError::DirtyNormalForm)?;
        let [(chord, slot), end_identity] = map.arc_endpoints(arc).ok_or(ClosureError::DirtyNormalForm)?;
        let next = canonical[(i + 1) % canonical.len()];
        let next_identity = map.arc_endpoints(next).ok_or(ClosureError::DirtyNormalForm)?[0];
        if full || chord.0 >= count || slot >= 2 || endpoint_seen[chord.0][slot] || end_identity != next_identity {
            return Err(ClosureError::DirtyNormalForm);
        }
        if map.chord(chord)?.0[slot] != start || map.arc_sites(next).ok_or(ClosureError::DirtyNormalForm)?.0 != end {
            return Err(ClosureError::DirtyNormalForm);
        }
        if previous_site.is_some_and(|previous| {
            work.predicates += 1;
            boundary.compare_sites(previous, start) != Ordering::Less
        }) {
            return Err(ClosureError::DirtyNormalForm);
        }
        previous_site = Some(start);
        endpoint_seen[chord.0][slot] = true;
        if let Some(generator) = chord_generators[chord.0] {
            let endpoint = Endpoint { site: start, chord: chord.0, slot, generator };
            if start.side() == Side::Left { left.push(endpoint); } else { right.push(endpoint); }
        }
    }
    right.reverse();
    let mut ordered = Vec::with_capacity(left.len() + right.len());
    let (mut l, mut r) = (0, 0);
    while l < left.len() || r < right.len() {
        work.retained_visits += 1;
        if r == right.len() || (l < left.len() && position_cmp(left[l].site, right[r].site, work) != Ordering::Greater) {
            ordered.push(left[l]); l += 1;
        } else {
            ordered.push(right[r]); r += 1;
        }
    }

    // Merge in the original vertices, including those with only null/wrap rays.
    // Deduplication now preserves each chord endpoint's dense attachment ID.
    let mut nodes = Vec::with_capacity(n + ordered.len());
    let mut attachments = vec![[usize::MAX; 2]; count];
    let (mut v, mut e) = (0, 0);
    while v < original_order.len() || e < ordered.len() {
        if e == ordered.len() || (v < original_order.len()
            && vertex_position_cmp(original_order[v].0, ordered[e].site, work) != Ordering::Greater)
        {
            let original = original_order[v].1;
            attach_contact(&mut nodes, Contact::vertex(original), original, &vertices, work)?;
            v += 1;
        } else {
            let endpoint = ordered[e];
            let node = attach_contact(&mut nodes, Contact::of(input, endpoint.site)?, endpoint.generator, &vertices, work)?;
            attachments[endpoint.chord][endpoint.slot] = node;
            e += 1;
        }
    }
    let seam = nodes.iter().position(|node| node.contact.edge == 0 && node.contact.t.is_zero())
        .ok_or(ClosureError::InvalidEmbedding)?;
    let node_count = nodes.len();
    nodes.rotate_left(seam);
    for (index, generator) in chord_generators.iter().enumerate() {
        if generator.is_some() {
            for attached in &mut attachments[index] {
                if *attached == usize::MAX { return Err(ClosureError::DirtyNormalForm); }
                *attached = (*attached + node_count - seam) % node_count;
            }
        }
    }
    let mut area = Rational::zero();
    for i in 0..n {
        work.predicates += 1;
        let a = vertices[i]; let b = vertices[(i + 1) % n];
        if a.y == b.y { return Err(ClosureError::InvalidEmbedding); }
        area += &a.x * &b.y - &a.y * &b.x;
    }
    let winding = area.cmp(&Rational::zero());
    if winding == Ordering::Equal { return Err(ClosureError::InvalidEmbedding); }
    let ccw = winding == Ordering::Greater;
    let mut darts = Vec::with_capacity(2 * (node_count + ordered.len() / 2));
    for i in 0..node_count {
        let next = (i + 1) % node_count;
        let support = nodes[i].contact.edge;
        let next_contact = &nodes[next].contact;
        work.predicates += 1;
        if !(next_contact.edge == support && next_contact.t > nodes[i].contact.t)
            && !(next_contact.edge == (support + 1) % n && next_contact.t.is_zero())
        { return Err(ClosureError::InvalidEmbedding); }
        add_edge(&mut nodes, &mut darts, i, next, Some(support), Some(ccw))?;
    }
    for (index, generator) in chord_generators.iter().enumerate() {
        if let Some(generator) = generator {
            let [a, b] = attachments[index];
            work.predicates += 2;
            if nodes[a].point.point().y != vertices[*generator].y
                || nodes[b].point.point().y != vertices[*generator].y
                || nodes[a].point.point().x == nodes[b].point.point().x
            { return Err(ClosureError::InvalidEmbedding); }
            add_edge(&mut nodes, &mut darts, a, b, None, None)?;
        }
    }
    // Insertion sort is bounded by four darts, never an unbounded angular sort.
    for i in 0..nodes.len() {
        let degree = nodes[i].degree;
        let mut order = nodes[i].outgoing;
        for j in 1..degree {
            let mut k = j;
            while k > 0 {
                match angular_cmp(&nodes, i, darts[order[k - 1]].head, darts[order[k]].head, work) {
                    Ordering::Greater => { order.swap(k - 1, k); k -= 1; }
                    Ordering::Equal => return Err(ClosureError::InvalidEmbedding),
                    Ordering::Less => break,
                }
            }
        }
        for j in 0..degree { darts[order[j]].rot_prev = order[(j + degree - 1) % degree]; }
    }

    let mut visited = vec![false; darts.len()];
    let mut cycle = Vec::new();
    let mut cells = Vec::with_capacity(n - 1);
    let mut caps = vec![0usize; n];
    for start in 0..darts.len() {
        if visited[start] { continue; }
        cycle.clear();
        let mut current = start;
        let mut face_area = Rational::zero();
        let mut inside = None;
        let mut lower = darts[start].tail;
        let mut upper = lower;
        loop {
            work.retained_visits += 1;
            if visited[current] {
                if current != start { return Err(ClosureError::InvalidEmbedding); }
                break;
            }
            visited[current] = true;
            cycle.push(current);
            let dart = darts[current];
            let a = nodes[dart.tail].point.point();
            let b = nodes[dart.head].point.point();
            face_area += &a.x * &b.y - &a.y * &b.x;
            work.predicates += 2;
            if a.y < nodes[lower].point.point().y { lower = dart.tail; }
            if a.y > nodes[upper].point.point().y { upper = dart.tail; }
            if let Some(label) = dart.inside_left {
                if inside.replace(label).is_some_and(|old| old != label) {
                    return Err(ClosureError::InvalidEmbedding);
                }
            }
            current = darts[dart.twin].rot_prev;
        }
        if face_area.is_zero() { continue; }
        if !inside.ok_or(ClosureError::InvalidEmbedding)? { continue; }
        if face_area < Rational::zero() { return Err(ClosureError::InvalidEmbedding); }
        let low_y = &nodes[lower].point.point().y;
        let high_y = &nodes[upper].point.point().y;
        if low_y >= high_y { return Err(ClosureError::InvalidCell); }
        let generators = [nodes[lower].generator, nodes[upper].generator];
        let mut supports = [usize::MAX; 2];
        for &id in &cycle {
            work.retained_visits += 1;
            let dart = darts[id];
            let node = &nodes[dart.tail];
            let y = &node.point.point().y;
            if (y == low_y && node.generator != generators[0])
                || (y == high_y && node.generator != generators[1])
            { return Err(ClosureError::InvalidCell); }
            if let Some(support) = dart.support {
                if !supports.contains(&support) {
                    if supports[0] == usize::MAX { supports[0] = support; }
                    else if supports[1] == usize::MAX { supports[1] = support; }
                    else { return Err(ClosureError::InvalidCell); }
                }
            } else if y != low_y && y != high_y {
                return Err(ClosureError::InvalidCell);
            }
            if matches!(node.point, PhysicalPoint::Original(_)) && y != low_y && y != high_y {
                return Err(ClosureError::InvalidCell);
            }
        }
        if supports.contains(&usize::MAX) { return Err(ClosureError::InvalidCell); }
        for &support in &supports {
            let a = vertices[support]; let b = vertices[(support + 1) % n];
            work.predicates += 2;
            if std::cmp::min(&a.y, &b.y) > low_y || std::cmp::max(&a.y, &b.y) < high_y {
                return Err(ClosureError::InvalidCell);
            }
        }
        let mid_y = (low_y + high_y) / Rational::from_integer(2.into());
        let x0 = edge_x(&vertices, supports[0], &mid_y);
        let x1 = edge_x(&vertices, supports[1], &mid_y);
        work.predicates += 1;
        if x0 == x1 { return Err(ClosureError::InvalidCell); }
        if x0 > x1 { supports.swap(0, 1); }
        for &generator in &generators {
            let point = vertices[generator];
            work.predicates += 2;
            if edge_x(&vertices, supports[0], &point.y) > point.x
                || edge_x(&vertices, supports[1], &point.y) < point.x
            { return Err(ClosureError::InvalidCell); }
            caps[generator] += 1;
        }
        cells.push(Cell { generators, left_edge: supports[0], right_edge: supports[1] });
    }
    // Completeness also has a local closed-map witness: ordinary vertices have
    // two caps, convex extrema one, and reflex extrema three, in either winding.
    for i in 0..n {
        let prev = vertices[(i + n - 1) % n];
        let point = vertices[i];
        let next = vertices[(i + 1) % n];
        work.predicates += 2;
        let expected = if (point.y > prev.y) != (next.y > point.y) {
            work.predicates += 1;
            let turn = orientation(prev, point, next);
            if turn == Ordering::Equal { return Err(ClosureError::InvalidEmbedding); }
            if turn == winding { 1 } else { 3 }
        } else { 2 };
        if caps[i] != expected {
            return Err(ClosureError::InvalidCapIncidence { vertex: i, expected, actual: caps[i] });
        }
    }
    Ok(ClosedVisibility { vertices, cells })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::base::full_visibility;
    use crate::boundary::Chain;
    use crate::reduction::triangulate_visibility;
    use crate::submap::VisibleChord;
    use std::collections::BTreeMap;

    fn cell(lower: usize, upper: usize, left: usize, right: usize) -> Cell {
        Cell { generators: [lower, upper], left_edge: left, right_edge: right }
    }
    fn assert_cells(actual: &[Cell], expected: &[Cell]) {
        let key = |cell: &Cell| (cell.generators, cell.left_edge, cell.right_edge);
        let mut actual: Vec<_> = actual.iter().map(key).collect();
        let mut expected: Vec<_> = expected.iter().map(key).collect();
        actual.sort_unstable();
        expected.sort_unstable();
        assert_eq!(actual, expected);
    }
    fn check_case(points: &[(i64, i64)], expected: &[Cell]) {
        let points: Vec<_> = points.iter().map(|&(x, y)| Point::integer(x, y)).collect();
        for reverse in [false, true] {
            let ordered: Vec<_> = if reverse { points.iter().rev().cloned().collect() } else { points.clone() };
            let input = Input::polygon(&ordered).unwrap();
            let chain = Chain::new(&input, VertexId(0), VertexId(input.len() - 1)).unwrap();
            assert!(chain.edge_count() <= crate::base::MAX_BASE_EDGES);
            let boundary = Boundary::new(&input, chain).unwrap();
            let mut work = Work::default();
            let map = full_visibility(boundary, &mut work).unwrap();
            let closed = close_visibility(&map, &mut work).unwrap();
            let n = points.len();
            let expected: Vec<_> = expected.iter().map(|cell| {
                if reverse {
                    Cell {
                        generators: cell.generators.map(|v| n - 1 - v),
                        left_edge: (2 * n - 2 - cell.left_edge) % n,
                        right_edge: (2 * n - 2 - cell.right_edge) % n,
                    }
                } else { *cell }
            }).collect();
            assert_cells(&closed.cells, &expected);
            for index in 0..input.len() {
                if let VertexSource::Original(original) = input.source(VertexId(index)) {
                    assert!(std::ptr::eq(closed.vertices[*original], input.vertex(VertexId(index))));
                }
            }
            // This copy is deliberately test-only until reduction accepts
            // borrowed point access. Production closure returns table borrows.
            let copied: Vec<_> = closed.vertices.iter().map(|point| (*point).clone()).collect();
            let triangles = triangulate_visibility(&copied, &closed.cells, &mut work).unwrap();
            assert_eq!(triangles.len(), n - 2);
            let mut triangle_area = Rational::zero();
            let mut edges = BTreeMap::new();
            let mut covered = vec![false; n];
            for [a, b, c] in triangles {
                assert_eq!(orientation(&copied[a], &copied[b], &copied[c]), Ordering::Greater);
                triangle_area += (&copied[b].x - &copied[a].x) * (&copied[c].y - &copied[a].y)
                    - (&copied[b].y - &copied[a].y) * (&copied[c].x - &copied[a].x);
                for v in [a, b, c] { covered[v] = true; }
                for (u, v) in [(a, b), (b, c), (c, a)] {
                    *edges.entry((u.min(v), u.max(v))).or_insert(0) += 1;
                }
            }
            let mut polygon_area = Rational::zero();
            for i in 0..n {
                let a = &copied[i]; let b = &copied[(i + 1) % n];
                polygon_area += &a.x * &b.y - &a.y * &b.x;
                assert_eq!(edges.get(&(i.min((i + 1) % n), i.max((i + 1) % n))), Some(&1));
            }
            assert_eq!(triangle_area, if polygon_area < Rational::zero() { -polygon_area } else { polygon_area });
            assert!(covered.into_iter().all(|value| value));
            for ((a, b), count) in edges {
                assert_eq!(count, if (a + 1) % n == b || (b + 1) % n == a { 1 } else { 2 });
            }
        }
    }

    #[test]
    fn triangle_caps_are_original_vertices_not_ray_landings() {
        check_case(&[(0, 0), (4, 0), (1, 3)], &[cell(0, 1, 2, 0), cell(1, 2, 2, 1)]);
    }
    #[test]
    fn convex_cells_keep_exact_original_supports_in_both_windings() {
        check_case(&[(0, 0), (4, 0), (4, 3), (0, 3)], &[
            cell(0, 1, 3, 0), cell(1, 3, 3, 1), cell(3, 2, 2, 1),
        ]);
    }
    #[test]
    fn reflex_cap_generates_three_cells_with_original_provenance() {
        check_case(&[(0, 0), (6, 0), (6, 5), (3, 2), (0, 5)], &[
            cell(0, 1, 4, 0), cell(1, 3, 4, 1), cell(3, 4, 4, 3), cell(3, 2, 2, 1),
        ]);
    }
    #[test]
    fn bounded_positive_area_exterior_faces_are_not_cells() {
        check_case(&[(0, 0), (6, 0), (6, 6), (4, 6), (4, 2), (2, 2), (2, 6), (0, 6)], &[
            cell(0, 1, 7, 0), cell(1, 5, 7, 1), cell(5, 7, 7, 5), cell(5, 4, 4, 1),
            cell(4, 3, 3, 1), cell(7, 6, 6, 5), cell(3, 2, 2, 1),
        ]);
    }
    #[test]
    fn collinear_original_vertices_still_generate_distinct_caps() {
        check_case(&[(0, 0), (2, 0), (4, 0), (4, 3), (0, 3)], &[
            cell(0, 1, 4, 0), cell(1, 2, 4, 1), cell(2, 4, 4, 2), cell(4, 3, 3, 2),
        ]);
    }
    #[test]
    fn missing_original_source_is_rejected_even_when_its_ray_is_not_retained() {
        let input = Input::polygon(&[Point::integer(0, 0), Point::integer(4, 0), Point::integer(1, 3)]).unwrap();
        let chain = Chain::new(&input, VertexId(0), VertexId(input.len() - 1)).unwrap();
        let boundary = Boundary::new(&input, chain).unwrap();
        let mut work = Work::default();
        let map = full_visibility(boundary, &mut work).unwrap();
        for discard in [Route::Finite, Route::Null, Route::Wrap] {
            let removed = map.chord_ids().find(|&id| {
                let (ends, route) = map.chord(id).unwrap();
                route == discard && ends.iter().any(|site| original_vertex(&input, site).is_some())
            }).unwrap();
            let missing: Vec<_> = map.chord(removed).unwrap().0.into_iter().filter_map(|site| {
                let original = original_vertex(&input, site)?;
                let Site::Vertex { side, slot, .. } = site else { unreachable!() };
                Some((original, *side, *slot))
            }).collect();
            let remaining = map.chord_ids().filter(|&id| id != removed).map(|id| {
                let (ends, route) = map.chord(id).unwrap();
                VisibleChord {
                    endpoints: [ends[0].clone(), ends[1].clone()], route,
                    level: map.chord_level(id).unwrap().clone(),
                }
            }).collect();
            let incomplete = Submap::from_verified_chords(&boundary, remaining, &mut work).unwrap();
            match close_visibility(&incomplete, &mut work) {
                Err(ClosureError::MissingOriginalSource { vertex, side, slot }) => {
                    // Null and full-circle chords can own two source flags;
                    // either absent endpoint is a precise coverage diagnostic.
                    assert!(missing.contains(&(vertex, side, slot)));
                }
                other => panic!("expected original coverage failure, got {other:?}"),
            }
        }
    }
    #[test]
    fn synthetic_only_rays_can_be_removed_but_normal_form_must_be_republished() {
        let input = Input::polygon(&[Point::integer(0, 0), Point::integer(4, 0), Point::integer(1, 3)]).unwrap();
        let chain = Chain::new(&input, VertexId(0), VertexId(input.len() - 1)).unwrap();
        let boundary = Boundary::new(&input, chain).unwrap();
        let mut work = Work::default();
        let mut map = full_visibility(boundary, &mut work).unwrap();
        let synthetic = map.chord_ids().find(|&id| {
            map.chord(id).unwrap().0.iter().all(|site| original_vertex(&input, site).is_none())
        }).unwrap();
        map.delete(synthetic).unwrap();
        assert!(matches!(close_visibility(&map, &mut work), Err(ClosureError::DirtyNormalForm)));
        map.rebuild_normal_form(&boundary, &mut work).unwrap();
        let closed = close_visibility(&map, &mut work).unwrap();
        assert_cells(&closed.cells, &[cell(0, 1, 2, 0), cell(1, 2, 2, 1)]);
    }
    #[test]
    fn open_input_and_partial_polygon_scope_are_rejected() {
        let points = [Point::integer(0, 0), Point::integer(4, 0), Point::integer(1, 3)];
        let mut work = Work::default();
        let open = Input::open(&points).unwrap();
        let boundary = Boundary::new(&open, Chain::new(&open, VertexId(0), VertexId(open.len() - 1)).unwrap()).unwrap();
        let map = full_visibility(boundary, &mut work).unwrap();
        assert!(matches!(close_visibility(&map, &mut work), Err(ClosureError::NotPolygon)));
        let polygon = Input::polygon(&points).unwrap();
        let boundary = Boundary::new(&polygon, Chain::new(&polygon, VertexId(1), VertexId(3)).unwrap()).unwrap();
        let map = full_visibility(boundary, &mut work).unwrap();
        assert!(matches!(close_visibility(&map, &mut work), Err(ClosureError::NotFullChain)));
    }
}
